WITH parsed AS (SELECT id, currency, tier_limits, tier_prices, discounts, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, SLICE(tier_limits, 1, 2) AS first_two_limits, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers) SELECT currency, CASE WHEN entry_price >= 27 THEN 'HIGH' ELSE 'LOW' END AS entry_price_tier, PERCENTILE_APPROX(entry_price, ARRAY(0.25, 0.5, 0.75)) AS entry_price_quartiles, COUNT(CASE WHEN currency = 'USD' THEN 1 END) AS usd_count, COUNT(*) FILTER (WHERE currency = 'EUR') AS eur_rows, MAX(entry_price) FILTER (WHERE currency = 'USD') AS usd_max_entry_price, ROUND(SUM(entry_price) / NULLIF(COUNT(CASE WHEN currency = 'USD' THEN 1 END), 0), 2) AS entry_price_per_usd FROM parsed GROUP BY CUBE (currency, CASE WHEN entry_price >= 27 THEN 'HIGH' ELSE 'LOW' END) ORDER BY entry_price_per_usd NULLS LAST
